   [36]={next_id=37, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你瞧瞧周围的环境，更何况你是自己一个人回来的，哪怕我在这儿把你杀掉也没有人能发现，除了帮我，你没有别的选择。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_311.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [37]={next_id=38, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="哦不对，你是一位战员，这么多年里，我还没有尝试过用战员进行试验，唔……外面那个你看到了吧？", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_311.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [38]={next_id=39, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她说的是被关起来的那个克隆体，深海回忆起对方的惨状，面露不忍。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_311.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
