   [40]={next_id=41, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你是怎么认为的呢？关于我，还有那个克隆体……对了，它的编号是077，是我所有的克隆体中和我最像的一个，我总是能从她身上看到自己的影子。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_311.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [41]={next_id=42, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="尤其是她在某些场合做出某些选择的时候，坦白说，我在那种情况下应该也不会有别的做法……所以我最为厌恶她，也因此选择了用她作为试验的对象。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_311.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [42]={next_id=43, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="丽娜看着深海愈发紧皱的眉头，不紧不慢地又炫耀了一番自己的成果。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_311.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [43]={next_id=44, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="试验很成功，就像那个笔记本里写的那样，我制造出了神经毒素，这将会是我完成克里安卡心愿的关键。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_311.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
