   [47]={next_id=48, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我听说过关于您……丽娜·德尔波的一些信息，您看起来与那些记录颇为不同。", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_311.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [48]={next_id=49, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="人总不可能一成不变，更何况一百年的时间，已经足够让一个人成为另一个人了。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_311.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
