   [66]={next_id=67, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她的呼吸一下子急促了起来，不太敢相信丽娜的话。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [67]={next_id=68, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="您为什么会把这么重要的东西交给我？", msg_color="", msg_size=0, talker="深海", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "3109", 0, 0, -13.5, 206}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [68]={next_id=69, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="丽娜微笑看着她，神情颇为安详从容。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [69]={next_id=70, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="就像我对你说的那样，我活了一百多年了，这个时间足够让我成为另一个人，而我也确实被它所重塑了。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [70]={next_id=71, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我毕生的梦想就是做出一个了不起的伟大作品，我的成果你也看到了，HEL-9415，无论过去还是未来，我相信没有谁能超越她。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [71]={next_id=72, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="丽娜仰起头，脸上仍然是那副温和的笑容，眼底却蕴着疯狂。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [72]={next_id=73, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="为了完成她，我付出太多了，你知道这中间我失败了多少次吗？", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [73]={next_id=74, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="9415是她的编号，而这个编号的来历也很简单，只是实验的次数。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [74]={next_id=75, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="这个过程中还有很多的异变体、修格尔，以及更多的人类，甚至连我的腿都是为了测试药剂而再也无法复原的。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [75]={next_id=76, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="丽娜说着，抬手撩起衣摆，给深海看自己萎缩到皮包骨的双腿，深海不由地打了个冷颤。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [76]={next_id=77, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="莱斯坦斯从劳格公馆地下发现的那些资料她都见过，其中百分之九十的研究被学界视为禁忌。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={}, model_pos={}, model_move_pos={}, model_exit={}, model_show_effect={}, update_model={}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [77]={next_id=78, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="你也是个研究员、是个学者，我想你肯定能理解我。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [78]={next_id=79, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她看向伏在深海肩头的啫喱，源晶兽察觉到她的视线，有些紧张地悄悄缩回了自己的触须。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [79]={next_id=80, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="作为附加条件，将这支药剂喂给它，让它获得一幅更强大的躯体，这样我才能完全相信你能够保护好这份资料。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [80]={next_id=81, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="她掌心托着两支小指大小的玻璃瓶来，里面是某种银色的液体：流淌缓慢犹如液态的金属，黑红的粒子在其中涌动。", msg_color="", msg_size=0, talker="", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,0}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
   [81]={next_id=82, abreast_id={}, pType =1, cg_type =10, dialog=1, msg="我仿造因斐诺的研究制造出了这种进化药剂，只需要一滴，这个小家伙就可以摆脱这副孱弱的形态，或许不止是保护资料，你甚至可以保护链尉官。", msg_color="", msg_size=0, talker="丽娜", audio="", img="arts/ui/bg/story/storybg_302.jpg", video_url="", music_id="0", background_music="", model_tid={{ 2, "7200", 0, 0, 10, 222.5}}, model_pos={{ 0,0,0}}, model_move_pos={}, model_exit={}, model_show_effect={{}}, update_model={{ 2,1}}, role_act={}, head_path="", shake_ani=0, grad_time=0, is_memory=0, roll_str="",roll_bg ="", static_pic ="", prefab_path ="", runTalkTime =0, destoryTime =0, clickTimes =0, effPos={ 0,0,0},effUrl="", waitIDs = {}},
